#include <bits/stdc++.h>
using namespace std;

vector<int> uf;
int find(int x) { return uf[x] == x ? x : uf[x] = find(uf[x]); }
bool unite(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return false;
    uf[a] = b;
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<int> U(m), V(m);
    vector<long long> W(m);
    for (int i = 0; i < m; ++i) cin >> U[i] >> V[i] >> W[i];

    vector<int> ord(m);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int a, int b) { return W[a] < W[b]; });

    // 1) 先求原图的一棵 MST
    uf.resize(n + 1);
    iota(uf.begin(), uf.end(), 0);
    vector<char> inMST(m, 0);
    long long sum = 0;
    int used = 0;
    for (int id : ord) {
        if (U[id] == V[id]) continue;              // 自环不可能是树边
        if (unite(U[id], V[id])) { inMST[id] = 1; sum += W[id]; ++used; }
    }
    if (used != n - 1) {                           // 原图不连通：删任何边都不存在 MST
        for (int i = 0; i < m; ++i) cout << -1 << '\n';
        return 0;
    }

    // 2) 建出这棵 MST，并预处理深度/父边
    vector<vector<pair<int, int>>> tree(n + 1);
    for (int id = 0; id < m; ++id)
        if (inMST[id]) {
            tree[U[id]].push_back({V[id], id});
            tree[V[id]].push_back({U[id], id});
        }
    vector<int> dep(n + 1, 0), par(n + 1, 0), parE(n + 1, -1);
    vector<char> seen(n + 1, 0);
    vector<int> stk{1};
    seen[1] = 1;
    while (!stk.empty()) {
        int u = stk.back(); stk.pop_back();
        for (auto [v, id] : tree[u]) {
            if (seen[v]) continue;
            seen[v] = 1;
            dep[v] = dep[u] + 1;
            par[v] = u;
            parE[v] = id;
            stk.push_back(v);
        }
    }

    // 3) 非树边按边权升序，用并查集跳跃给树边打上“最小替换边”
    vector<long long> best(m, -1);
    vector<int> jump(n + 1);
    iota(jump.begin(), jump.end(), 0);
    function<int(int)> jf = [&](int x) { return jump[x] == x ? x : jump[x] = jf(jump[x]); };
    for (int id : ord) {
        if (inMST[id]) continue;
        int a = jf(U[id]), b = jf(V[id]);
        while (a != b) {
            if (dep[a] < dep[b]) swap(a, b);
            best[parE[a]] = W[id];   // 这条树边第一次被覆盖，即其最小替换边
            jump[a] = par[a];
            a = jf(a);
        }
    }

    // 4) 输出：非树边删去不影响 MST；树边看是否有替换边
    for (int i = 0; i < m; ++i) {
        if (!inMST[i]) cout << sum << '\n';
        else if (best[i] < 0) cout << -1 << '\n';
        else cout << sum - W[i] + best[i] << '\n';
    }
    return 0;
}
